+}
+export function searchTerms(text: string) {
+  const stop = new Set("a an the is are was were how what why can could do does did i my me you your please it this that for to of and with in on have has about".split(" "));
+  return [...new Set(normalizeQuestion(text).split(" ").filter((t) => t.length > 1 && t.length <= 32 && !stop.has(t)))].slice(0, 16).join(" ");
