+export function chunkKnowledge(pages: Passage[]): Passage[] {
+  const result: Passage[] = [];
+  for (const page of pages) {
+    let heading = page.heading || "Document", buffer = "";
+    const push = () => { if (buffer.trim()) result.push({ ...page, heading, text: buffer.trim() }); };
+    for (const paragraph of page.text.replace(/\r\n/g, "\n").split(/\n\s*\n/)) {
+      if (/^#{1,6}\s+/.test(paragraph) && buffer) { push(); buffer = ""; }
