+export function fuseKnowledge<T extends { _id: string; sourceId: string }>(keyword: T[], semantic: T[]) {
+  const hits = new Map<string, { item: T; score: number }>();
+  for (const list of [keyword, semantic]) list.forEach((item, rank) => {
+    const previous = hits.get(item._id);
+    hits.set(item._id, { item, score: (previous?.score || 0) + 1 / (60 + rank + 1) });
